/**
 * Hypium 兼容的最小实现（仅 Node 侧离线跑纯逻辑用例）。
 *
 * 这不是设备测试框架：它只实现 entry/domain 两套 Hypium 用例用到的
 * describe/it/expect/xhsRun 子集，让仓库里一条命令就能复现结果，
 * 不依赖 DevEco 注入的测试运行时。真机 Instrument Test 仍走 @ohos/hypium 本体
 * （见 docs/testing-checklist.md 与 entry/src/ohosTest）。
 *
 * 用法：CRD_ONLY=<用例名子串> 可只跑某一个 describe。
 */
const suites = [];
let current = null;

function describe(name, fn) {
  const suite = { name: name, cases: [] };
  suites.push(suite);
  const prev = current;
  current = suite;
  fn();
  current = prev;
}

function it(name, level, fn) {
  if (typeof level === 'function') {
    fn = level;
  }
  if (!current) {
    throw new Error('it() outside describe(): ' + name);
  }
  current.cases.push({ name: name, fn: fn });
}

class AssertionError extends Error {
}

function show(v) {
  return typeof v === 'object' ? JSON.stringify(v) : String(v);
}

function expect(actual) {
  return {
    assertEqual(expected) {
      if (actual !== expected) {
        throw new AssertionError('expected ' + show(expected) + ' but got ' + show(actual));
      }
    },
    assertTrue() {
      if (actual !== true) {
        throw new AssertionError('expected true but got ' + show(actual));
      }
    },
    assertFalse() {
      if (actual !== false) {
        throw new AssertionError('expected false but got ' + show(actual));
      }
    },
    assertNull() {
      if (actual !== null && actual !== undefined) {
        throw new AssertionError('expected null but got ' + show(actual));
      }
    },
    assertUndefined() {
      if (actual !== undefined) {
        throw new AssertionError('expected undefined but got ' + show(actual));
      }
    },
    assertLarger(expected) {
      if (!(actual > expected)) {
        throw new AssertionError('expected ' + show(actual) + ' > ' + show(expected));
      }
    },
    assertLess(expected) {
      if (!(actual < expected)) {
        throw new AssertionError('expected ' + show(actual) + ' < ' + show(expected));
      }
    },
    assertContain(expected) {
      const has = Array.isArray(actual)
        ? actual.indexOf(expected) >= 0 : String(actual).indexOf(String(expected)) >= 0;
      if (!has) {
        throw new AssertionError('expected ' + show(actual) + ' to contain ' + show(expected));
      }
    }
  };
}

function xhsRun() {
  const only = process.env.CRD_ONLY || '';
  let pass = 0;
  const failures = [];
  for (const suite of suites) {
    if (only && suite.name.indexOf(only) < 0) {
      continue;
    }
    console.log('\n' + suite.name);
    for (const c of suite.cases) {
      try {
        c.fn();
        pass++;
        console.log('  PASS ' + c.name);
      } catch (e) {
        const msg = e && e.message ? e.message : String(e);
        failures.push({ suite: suite.name, name: c.name, msg: msg });
        console.log('  FAIL ' + c.name + '  -- ' + msg);
      }
    }
  }
  console.log('\n' + pass + ' passed, ' + failures.length + ' failed, '
    + (pass + failures.length) + ' total');
  return failures.length === 0 ? 0 : 1;
}

module.exports = {
  describe: describe, it: it, expect: expect, xhsRun: xhsRun,
  beforeAll: () => {
  }, afterAll: () => {
  }, beforeEach: () => {
  }, afterEach: () => {
  }, beforeItSpec: () => {
  }, afterItSpec: () => {
  }
};
